// Reference implementation — the grounding gate (steps 2, 4, 8) + the grade
// primitive (step 7). Provider-neutral. Adapt to your fact shape; don't copy blind.
//
// Core idea: classify every fact as GROUNDED, SILENT, or VIOLATION. Only GROUNDED
// facts reach the model. SILENT is honest absence. VIOLATION never ships and is
// what you measure against.

export interface Fact {
  value: unknown;
  source?: string;
  observedAt?: number;   // epoch ms
  confidence?: number;   // 0..1
  ttlMinutes?: number;   // producer-declared freshness; falls back to default
  silentReason?: string; // set => a typed absence, not a claim
}

export type Verdict =
  | { kind: 'GROUNDED'; fact: Fact }
  | { kind: 'SILENT'; reason: string }
  | { kind: 'VIOLATION'; reason: string; cardinal: boolean };

const CARDINAL_CONFIDENCE = 0.7;   // confidence >= this with no source = impossible
const DEFAULT_TTL_MINUTES = 1440;  // conservative: unknowns are NOT spoken as fresh

export function classify(fact: Fact, now = Date.now()): Verdict {
  // Typed absence is first-class integrity, not a failure.
  if (fact.silentReason || fact.value == null) {
    return { kind: 'SILENT', reason: fact.silentReason ?? 'no-signal' };
  }
  const hasSource = !!fact.source;

  // The cardinal sin: confident claim with no source.
  if (fact.confidence != null && fact.confidence >= CARDINAL_CONFIDENCE && !hasSource) {
    return { kind: 'VIOLATION', reason: 'confident claim with no source', cardinal: true };
  }
  // Provenance is mandatory for any real claim.
  if (!hasSource || fact.observedAt == null) {
    return { kind: 'VIOLATION', reason: 'missing provenance (source/observedAt)', cardinal: false };
  }
  // Staleness: past its freshness window => strip, don't speak as current.
  const ttl = (fact.ttlMinutes ?? DEFAULT_TTL_MINUTES) * 60_000;
  if (now - fact.observedAt > ttl) {
    return { kind: 'VIOLATION', reason: 'stale beyond TTL', cardinal: false };
  }
  return { kind: 'GROUNDED', fact };
}

// Only GROUNDED facts are handed to the model. VIOLATIONs are dropped;
// SILENTs are passed to the render layer as typed absence to handle deliberately.
export function forModel(facts: Fact[], now = Date.now()): { grounded: Fact[]; silent: Verdict[] } {
  const grounded: Fact[] = [];
  const silent: Verdict[] = [];
  for (const f of facts) {
    const v = classify(f, now);
    if (v.kind === 'GROUNDED') grounded.push(v.fact);
    else if (v.kind === 'SILENT') silent.push(v);
    // VIOLATION: intentionally dropped — never reaches the model or the user.
  }
  return { grounded, silent };
}

// The grounding metric — silence counts as integrity, only violations count against.
export function groundingRate(facts: Fact[], now = Date.now()): number {
  let ok = 0, violation = 0;
  for (const f of facts) {
    const v = classify(f, now);
    if (v.kind === 'VIOLATION') violation++;
    else ok++; // GROUNDED and SILENT both count as integrity
  }
  const total = ok + violation;
  return total === 0 ? 1 : ok / total;
}

// The grade primitive (step 7): re-run today's rules over a historical snapshot,
// so accuracy fixes are evidence-driven across the population, not anecdote-driven.
export function grade(snapshot: Fact[], now = Date.now()): { rate: number; violations: Verdict[] } {
  const violations = snapshot
    .map(f => classify(f, now))
    .filter((v): v is Extract<Verdict, { kind: 'VIOLATION' }> => v.kind === 'VIOLATION');
  return { rate: groundingRate(snapshot, now), violations };
}

// Reference implementation — the deterministic anti-pattern detector (step 7a).
// Runs inline on 100% of output in <10ms. Hard rules fail (and the mechanical
// ones auto-repair); soft rules only fail on accumulation. Replace the RULES
// with YOUR team's named quality bar — these examples are illustrative, not law.

export interface Rule {
  id: string;
  test: RegExp;
  repair?: (s: string) => string; // present => mechanically fixable, applied in-memory
}

// HARD rules: one hit = fail. Give the fixable ones a `repair`.
export const HARD_RULES: Rule[] = [
  { id: 'em-dash', test: /—/g, repair: s => s.replace(/\s*—\s*/g, ', ') },
  { id: 'double-space', test: /  +/g, repair: s => s.replace(/  +/g, ' ') },
  // ... your named anti-patterns go here (e.g. banned phrases, forbidden framings)
];

// SOFT rules: a single hit is fine; N+ within a window is a tic. One shared
// regex of "tell" words; the threshold is what flags it.
export const SOFT_TELLS = /\b(delve|nuanced|intricate|palpable|profound|evocative|tapestry|realm)\b/gi;
const SOFT_THRESHOLD = 2; // 2+ tells per ~200 words = flag

export interface CritiqueResult {
  pass: boolean;
  repaired: string;          // the (possibly auto-repaired) text
  hardFindings: string[];    // rule ids that fired after repair
  softCount: number;
  autoRepairs: number;
}

export function critique(input: string): CritiqueResult {
  let text = input;
  let autoRepairs = 0;

  // Apply mechanical repairs first, count them.
  for (const rule of HARD_RULES) {
    if (rule.repair && rule.test.test(text)) {
      const before = text;
      text = rule.repair(text);
      if (text !== before) autoRepairs++;
    }
  }

  // Re-check hard rules AFTER repair — only unrepairable residue counts.
  const hardFindings = HARD_RULES
    .filter(r => { r.test.lastIndex = 0; return r.test.test(text); })
    .map(r => r.id);

  const softCount = (text.match(SOFT_TELLS) ?? []).length;

  return {
    pass: hardFindings.length === 0 && softCount < SOFT_THRESHOLD,
    repaired: text,
    hardFindings,
    softCount,
    autoRepairs,
  };
}

// Reference implementation — the fail-open prompt assembler (step 2 + 3).
// Provider-neutral: you supply a PromptStore (Langfuse / LangSmith / Braintrust /
// your own) and an in-code fallback. Adapt types to your stack; do not copy blind.
//
// The one invariant: assemble() NEVER throws on a store outage. Telemetry may
// degrade; user delivery never fails.

export interface ManagedPrompt {
  version: string;
  template: string; // may contain {{variables}}
}

export interface PromptStore {
  // Fetch the prompt labeled `production` for this name. May throw / time out —
  // the assembler is responsible for surviving that.
  fetch(name: string, label?: string): Promise<ManagedPrompt>;
}

// ---- short-TTL cache with an indefinitely-held last-good fallback (step 3) ----

interface CacheEntry { value: ManagedPrompt; fetchedAt: number; }

export class PromptCache {
  private fresh = new Map<string, CacheEntry>();
  private lastGood = new Map<string, ManagedPrompt>(); // never evicted

  constructor(
    private store: PromptStore,
    private ttlMs = 10_000,
    private now: () => number = () => Date.now(),
  ) {}

  async get(name: string): Promise<ManagedPrompt | null> {
    const hit = this.fresh.get(name);
    if (hit && this.now() - hit.fetchedAt < this.ttlMs) return hit.value;
    try {
      const value = await this.store.fetch(name, 'production');
      this.fresh.set(name, { value, fetchedAt: this.now() });
      this.lastGood.set(name, value); // remember the last thing that worked
      return value;
    } catch {
      // Store is down or slow. Serve the last thing that worked, forever.
      return this.lastGood.get(name) ?? null;
    }
  }
}

// ---- the assembler: managed -> compile -> in-code fallback -> usable default ----

export interface AssembleArgs {
  name: string;
  variables?: Record<string, string>;
  fallbackTemplate: string;   // the in-code cold-start copy (step 1)
  lastResort?: string;        // returned if even compilation fails; default ''
}

export interface AssembledPrompt {
  text: string;
  source: 'managed' | 'fallback' | 'lastResort';
  version?: string;           // set when source === 'managed' (link this in traces, step 5)
}

function compile(template: string, vars: Record<string, string> = {}): string {
  return template.replace(/\{\{\s*(\w+)\s*\}\}/g, (_, k) => vars[k] ?? '');
}

export async function assemble(
  cache: PromptCache,
  { name, variables, fallbackTemplate, lastResort = '' }: AssembleArgs,
): Promise<AssembledPrompt> {
  try {
    const managed = await cache.get(name);
    if (managed) {
      return { text: compile(managed.template, variables), source: 'managed', version: managed.version };
    }
  } catch {
    // fall through — never let the store break delivery
  }
  try {
    return { text: compile(fallbackTemplate, variables), source: 'fallback' };
  } catch {
    return { text: lastResort, source: 'lastResort' };
  }
}

/**
 * reference/chunk-and-pace.ts — provider-neutral shape for splitting a
 * script into synthesis chunks, classifying pauses, and re-assembling the
 * final audio with correct pacing and consistent loudness.
 *
 * This is a pattern to ADAPT, not a drop-in library. Swap the TTS call, the
 * silence-synthesis call, and the concat/loudnorm call for your own
 * provider's SDK / your own audio toolchain. No vendor-specific code here —
 * see RECIPE.md steps 2-3 and 6-7 for the reasoning behind each shape.
 */

// ── 1. Parse the script into text blocks + standalone pause markers ───────

type ScriptItem =
  | { type: 'text'; text: string }
  | { type: 'pause'; seconds: number }

/**
 * Split a script on blank lines into ordered items: spoken text blocks and
 * standalone `<pause seconds="N"/>`-style markers the author placed between
 * passages. Adapt the marker syntax to whatever your authoring pipeline
 * uses (SSML <break/>, a custom tag, plain "..." conventions).
 */
function parseScript(script: string): ScriptItem[] {
  const blocks = script.split(/\n\s*\n/).map((b) => b.trim()).filter(Boolean)
  return blocks.map((b) => {
    const m = b.match(/^<pause seconds="(\d+(?:\.\d+)?)"\s*\/?>$/i)
    return m ? { type: 'pause', seconds: parseFloat(m[1]) } : { type: 'text', text: b }
  })
}

// ── 2. Group into chunks, deciding which pauses become REAL silence ───────

interface Chunk {
  rawText: string
  /** Seconds of REAL reinjected silence to splice in after this chunk. */
  silenceAfterSec: number
}

/**
 * Group text blocks into at most `maxChunks` synthesis chunks, choosing the
 * `maxChunks - 1` LARGEST standalone pauses as real chunk-boundary silence.
 * Every other pause (smaller, or falling inside a merged chunk) gets
 * re-inlined as a token for the per-tier intra-chunk transform to handle
 * natively (see step 3 below) — it still paces, just not as spliced silence.
 *
 * Tune `maxChunks` and your own target-words-per-chunk against the SPECIFIC
 * tier's measured per-request latency (RECIPE.md step 2) — a size that's
 * right for a fast tier creates a straggler tail on a slow one.
 */
function groupIntoChunks(items: ScriptItem[], maxChunks: number): Chunk[] {
  type Base = { rawText: string; pauseAfterSec: number }
  const base: Base[] = []
  for (const it of items) {
    if (it.type === 'text') base.push({ rawText: it.text, pauseAfterSec: 0 })
    else if (base.length > 0) base[base.length - 1].pauseAfterSec += it.seconds
    // a leading pause with nothing to attach to is dropped — nothing to hold silence before
  }

  if (base.length <= maxChunks) {
    return base.map((b) => ({ rawText: b.rawText, silenceAfterSec: b.pauseAfterSec }))
  }

  const boundaryCount = base.length - 1
  const keep = Math.max(1, maxChunks - 1)
  const chosen = new Set(
    Array.from({ length: boundaryCount }, (_, i) => i)
      .sort((a, b) => base[b].pauseAfterSec - base[a].pauseAfterSec || a - b)
      .slice(0, keep),
  )

  const chunks: Chunk[] = []
  let parts: string[] = []
  for (let i = 0; i < base.length; i++) {
    parts.push(base[i].rawText)
    const isLast = i === base.length - 1
    if (isLast) {
      chunks.push({ rawText: parts.join('\n\n'), silenceAfterSec: 0 })
      break
    }
    const gap = base[i].pauseAfterSec
    if (chosen.has(i)) {
      chunks.push({ rawText: parts.join('\n\n'), silenceAfterSec: gap })
      parts = []
    } else if (gap > 0) {
      parts.push(`<pause seconds="${gap}"/>`) // re-inlined for the intra-chunk transform
    }
  }
  return chunks
}

// ── 3. Per-tier intra-chunk transform: what a pause becomes INSIDE a chunk ─

interface VoiceTier {
  id: string
  /** Does this tier honor a literal pause marker natively, or does it need
   *  translation to inline cue tags ("[short pause]" style)? */
  honorsNativePauseMarker: boolean
  /** Stability/consistency setting. Raise this for any tier that synthesizes
   *  chunks INDEPENDENTLY with no cross-chunk context — low stability lets
   *  the voice "wander" (accent, persona) chunk to chunk (RECIPE.md: accent
   *  drift failure mode). */
  stability: number
}

function intraChunkText(rawText: string, tier: VoiceTier): string {
  if (tier.honorsNativePauseMarker) {
    // Tier reads the marker natively — leave it alone.
    return rawText
  }
  // Tier needs translation to inline cue tags it actually understands.
  return rawText.replace(/<pause seconds="(\d+(?:\.\d+)?)"\s*\/?>/gi, (_, sec) =>
    parseFloat(sec) <= 1.5 ? ' [short pause] ' : ' [long pause] ',
  )
}

// ── 4. Synthesize chunks, bounded by the provider's concurrency ceiling ───

/** Run `fn` over `items` in waves of at most `concurrency`, preserving order. */
async function runInWaves<T, R>(
  items: T[],
  concurrency: number,
  fn: (item: T) => Promise<R>,
): Promise<R[]> {
  const out: R[] = []
  for (let i = 0; i < items.length; i += concurrency) {
    const wave = items.slice(i, i + concurrency)
    out.push(...(await Promise.all(wave.map(fn))))
  }
  return out
}

/**
 * Synthesize one chunk with an OWN, strongly-referenced timeout chained to a
 * caller abort signal. RECIPE.md step 5: a composite/derived AbortSignal with
 * nothing holding the timeout strongly can silently never fire in some
 * runtimes, hanging the request and starving a shared concurrency slot.
 */
async function synthesizeChunk(
  text: string,
  tier: VoiceTier,
  opts: { signal?: AbortSignal; timeoutMs: number; ttsCall: (text: string, tier: VoiceTier, signal: AbortSignal) => Promise<Buffer> },
): Promise<Buffer> {
  const ac = new AbortController()
  const onExternalAbort = () => ac.abort()
  if (opts.signal) {
    if (opts.signal.aborted) ac.abort()
    else opts.signal.addEventListener('abort', onExternalAbort, { once: true })
  }
  const timer = setTimeout(() => ac.abort(), opts.timeoutMs) // explicit, strongly held
  try {
    return await opts.ttsCall(text, tier, ac.signal)
  } finally {
    clearTimeout(timer) // always clear — this is what makes the timeout GC-safe
    if (opts.signal) opts.signal.removeEventListener('abort', onExternalAbort)
  }
}

// ── 5. Reinject real silence at chosen boundaries, concat, normalize ──────

/**
 * Interleave chunk audio with reinjected silence, then concatenate by
 * RE-ENCODING (never raw byte-copy — RECIPE.md step 6) and fold loudness
 * normalization into that same encoding pass (step 7). `concatAndMaster`
 * is a stand-in for your own audio toolchain (e.g. an ffmpeg invocation
 * with a concat demuxer + a loudnorm filter in one pass).
 */
async function assembleFinalAudio(
  chunks: Chunk[],
  chunkAudio: Buffer[],
  deps: {
    makeSilence: (seconds: number) => Promise<Buffer>
    concatAndMaster: (buffers: Buffer[], loudnessTargetLufs: number, truePeakDb: number) => Promise<Buffer>
  },
  loudnessTargetLufs = -16,
  truePeakDb = -1.5,
): Promise<Buffer> {
  const interleaved: Buffer[] = []
  for (let i = 0; i < chunkAudio.length; i++) {
    interleaved.push(chunkAudio[i])
    const gap = chunks[i].silenceAfterSec
    if (gap > 0 && i < chunkAudio.length - 1) {
      // Stretch slightly and clamp — a proven pacing policy, not a magic number
      // you need to invent from scratch. See RECEIPTS-internal.md for the
      // exact multiplier and clamp used at origin.
      interleaved.push(await deps.makeSilence(gap))
    }
  }
  return deps.concatAndMaster(interleaved, loudnessTargetLufs, truePeakDb)
}

export { parseScript, groupIntoChunks, intraChunkText, runInWaves, synthesizeChunk, assembleFinalAudio }
export type { ScriptItem, Chunk, VoiceTier }
